* { box-sizing: border-box; }
:root {
  color-scheme: dark;
  font-family: system-ui, sans-serif;
  font-size: 16px;
  background: #17211f;
  color: #f5f2df;
  --ink: #17211f;
  --panel: #24312e;
  --line: #43534d;
  --cream: #f5f2df;
  --lime: #c4ee68;
  --orange: #ff9c57;
}
body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 36px 16px;
  display: grid;
  place-items: center;
  background-image: radial-gradient(ellipse at 50% 0%, #344640 0, var(--ink) 65%);
}
.board {
  width: min(880px, 100%);
  padding: clamp(22px, 5vw, 44px);
  border: 1px solid #50615a;
  border-radius: 18px;
  background: #202c29;
  box-shadow: 0 20px 70px #0b100f99;
}
.heading { text-align: center; margin-bottom: 30px; }
.eyebrow { margin: 0 0 9px; color: var(--lime); font-size: .8rem; font-weight: 800; letter-spacing: .16em; }
h1 { margin: 0; font-size: clamp(2rem, 7vw, 3.4rem); letter-spacing: -.05em; line-height: 1.1; }
.subtitle { margin: 12px 0 0; color: #c2ccc4; }
.score-section { overflow: hidden; border: 1px solid var(--line); border-radius: 12px; background: #192320; }
.score-grid { display: grid; grid-template-columns: repeat(9, minmax(0, 1fr)) minmax(0, 1.35fr); }
.frame { min-width: 0; min-height: 110px; border-right: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.frame:last-child { border-right: 0; }
.frame-head { padding: 8px 4px; text-align: center; background: #2b3934; color: #cbd5ca; font-size: .8rem; font-weight: 750; }
.rolls { height: 38px; display: flex; justify-content: flex-end; border-bottom: 1px solid var(--line); }
.roll { min-width: 25px; padding: 6px 3px; text-align: center; border-left: 1px solid var(--line); color: var(--cream); font-size: .86rem; font-weight: 750; }
.roll.mark { color: var(--lime); }
.frame-total { padding: 11px 4px 8px; text-align: center; color: var(--lime); font-size: 1.15rem; font-weight: 850; }
.frame-total.pending { color: #718078; }
.total-strip { min-height: 66px; padding: 12px 18px; display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.total-strip span { color: #cbd5ca; font-size: .82rem; font-weight: 800; letter-spacing: .12em; }
.total-strip strong { color: var(--lime); font-size: 2rem; line-height: 1; }
.controls { margin-top: 30px; }
.control-heading { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; margin-bottom: 12px; }
h2 { margin: 0; font-size: 1.05rem; }
#roll-status { color: var(--orange); font-weight: 750; }
.pin-buttons { display: grid; grid-template-columns: repeat(11, minmax(0, 1fr)); gap: 8px; }
.pin-button, .reset-button { min-height: 48px; border: 1px solid #596b62; border-radius: 9px; background: #2c3a35; color: var(--cream); font: inherit; font-weight: 800; cursor: pointer; transition: background .15s, transform .15s, border-color .15s; }
.pin-button:hover, .reset-button:hover { border-color: var(--lime); background: #394a42; }
.pin-button:focus-visible, .reset-button:focus-visible { outline: 3px solid var(--orange); outline-offset: 3px; }
.pin-button:active, .reset-button:active { transform: translateY(2px); background: #46594e; }
.pin-button:disabled { cursor: not-allowed; opacity: .4; }
.pin-button.recommended { border-color: var(--lime); color: var(--lime); }
.actions { margin-top: 16px; display: flex; align-items: center; justify-content: space-between; gap: 14px; }
.reset-button { min-height: 42px; padding: 0 14px; font-size: .9rem; }
.hint { color: #aab8af; font-size: .85rem; text-align: right; }
footer { margin-top: 27px; color: #899a90; font-size: .85rem; text-align: center; }
@media (max-width: 600px) {
  body { padding: 18px 10px; }
  .board { padding: 22px 14px; }
  .score-section { overflow-x: auto; }
  .score-grid { min-width: 590px; }
  .pin-buttons { grid-template-columns: repeat(6, minmax(0, 1fr)); }
  .actions { align-items: flex-start; flex-direction: column; }
  .hint { text-align: left; }
}

const grid = document.querySelector('#score-grid');
const buttons = document.querySelector('#pin-buttons');
const status = document.querySelector('#roll-status');
const finalScore = document.querySelector('#final-score');
const rolls = [];
let done = false;

for (let i = 1; i <= 10; i++) {
  const frame = document.createElement('div');
  frame.className = 'frame';
  frame.setAttribute('role', 'cell');
  frame.innerHTML = `<div class="frame-head">FRAME ${i}</div><div class="rolls" aria-label="Rolls"></div><div class="frame-total pending">—</div>`;
  grid.append(frame);
}
for (let pins = 0; pins <= 10; pins++) {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'pin-button';
  button.textContent = pins;
  button.setAttribute('aria-label', `${pins} ${pins === 1 ? 'pin' : 'pins'}`);
  button.dataset.pins = pins;
  button.addEventListener('click', () => recordRoll(pins));
  buttons.append(button);
}

document.querySelector('#reset-button').addEventListener('click', () => {
  rolls.length = 0;
  done = false;
  render();
  buttons.querySelector('button').focus();
});

function frameRolls() {
  const frames = [];
  let i = 0;
  for (let f = 0; f < 9; f++) {
    if (rolls[i] === 10) { frames.push([i++]); }
    else if (rolls[i] !== undefined && rolls[i + 1] !== undefined) {
      frames.push([i, i + 1]); i += 2;
    } else { frames.push(rolls.slice(i)); i = rolls.length; }
  }
  frames.push(rolls.slice(i));
  return frames;
}
function currentMax() {
  const frames = frameRolls();
  const tenth = frames[9];
  if (frames.slice(0, 9).length && rolls.length >= 0) {
    const firstNineComplete = frames.slice(0, 9).every((f, n) => f.length === (rolls[f[0]] === 10 ? 1 : 2));
    if (!firstNineComplete) {
      const idx = rolls.length;
      const f = frames.findIndex((_, n) => n < 9 && (frames[n].length === 0 || (rolls[frames[n][0]] !== 10 && frames[n].length === 1)));
      if (f >= 0) {
        const frame = frames[f];
        return frame.length === 0 || rolls[frame[0]] === 10 ? 10 : 10 - rolls[frame[0]];
      }
    }
  }
  if (tenth.length === 0) return 10;
  const a = rolls[tenth[0]];
  if (a === undefined) return 10;
  if (a < 10) {
    if (tenth.length === 1) return 10 - a;
    return 10;
  }
  if (tenth.length === 1) return 10;
  if (tenth.length === 2 && rolls[tenth[1]] !== 10) return 10 - rolls[tenth[1]];
  return 10;
}
function recordRoll(pins) {
  if (done || pins > currentMax()) return;
  rolls.push(pins);
  const frames = frameRolls();
  const firstNineDone = frames.slice(0, 9).every(f => f.length && (rolls[f[0]] === 10 || f.length === 2));
  if (firstNineDone && frames[9].length === 3) done = true;
  if (firstNineDone && frames[9].length === 2) {
    const tenth = frames[9], a = rolls[tenth[0]], b = rolls[tenth[1]];
    if (a !== 10 && a + b < 10) done = true;
  }
  render();
}
function render() {
  const frames = frameRolls();
  const cells = [...grid.children];
  let cumulative = 0;
  let allKnown = true;
  frames.forEach((frame, n) => {
    const cell = cells[n];
    const rollBox = cell.querySelector('.rolls');
    rollBox.replaceChildren();
    const visible = n === 9 ? frame.slice(0, 3) : frame.slice(0, 2);
    visible.forEach((index, r) => {
      const value = rolls[index];
      const mark = n < 9 && ((r === 0 && value === 10) || (r === 1 && rolls[frame[0]] + value === 10));
      const span = document.createElement('span');
      span.className = `roll${mark ? ' mark' : ''}`;
      span.textContent = mark ? (value === 10 && r === 0 ? 'X' : '/') : value;
      rollBox.append(span);
    });
    let frameScore;
    if (n < 9) {
      const first = frame[0];
      if (first !== undefined && rolls[first] === 10 && rolls[first + 1] !== undefined && rolls[first + 2] !== undefined) frameScore = 10 + rolls[first + 1] + rolls[first + 2];
      else if (first !== undefined && rolls[first] !== 10 && frame.length === 2) {
        const sum = rolls[first] + rolls[first + 1];
        if (sum === 10 && rolls[first + 2] !== undefined) frameScore = 10 + rolls[first + 2];
        else if (sum < 10) frameScore = sum;
      }
    } else if (frame.length === 3 || (frame.length === 2 && rolls[frame[0]] !== 10 && rolls[frame[0]] + rolls[frame[1]] < 10)) frameScore = frame.reduce((s, idx) => s + rolls[idx], 0);
    const total = cell.querySelector('.frame-total');
    if (frameScore === undefined || !allKnown) {
      total.textContent = '—'; total.classList.add('pending'); allKnown = false;
    } else {
      cumulative += frameScore;
      total.textContent = cumulative; total.classList.remove('pending');
    }
  });
  const firstNineDone = frames.slice(0, 9).every(f => f.length && (rolls[f[0]] === 10 || f.length === 2));
  if (done && firstNineDone) {
    const tenthScore = frames[9].reduce((s, idx) => s + rolls[idx], 0);
    const previousTotal = Number(cells[8].querySelector('.frame-total').textContent) || 0;
    const tenthTotal = previousTotal + tenthScore;
    cells[9].querySelector('.frame-total').textContent = tenthTotal;
    cells[9].querySelector('.frame-total').classList.remove('pending');
    finalScore.textContent = tenthTotal;
    status.textContent = `Game complete · ${rolls.length} rolls`;
  } else {
    finalScore.textContent = '—';
    status.textContent = done ? 'Game complete' : `Roll ${rolls.length + 1}`;
  }
  buttons.querySelectorAll('button').forEach(button => {
    const value = Number(button.dataset.pins);
    button.disabled = done || value > currentMax();
    button.classList.toggle('recommended', !button.disabled && value === currentMax());
  });
}
render();
